mapper.select:
SELECT 
FROM api_key
WHERE active = 1

    AND (name LIKE CONCAT('%', #{keyword}, '%')
         OR key_prefix LIKE CONCAT('%', #{keyword}, '%'))


    AND enabled = #{enabled}


    AND creator = #{creator}


    AND tenant_id = #{tenantId}

ORDER BY create_time DESC
